<?php
require __DIR__.'/base.php';$id=autenticado();$db=banco();$sol=(int)($_GET['id_solicitacao']??0);
if(!$sol){$stmt=$db->prepare("SELECT s.id_solicitacao,i.nome AS produto,s.status_soli,us.nome AS solicitante,ud.nome AS doador FROM solicitacao s JOIN solicitacao_item si ON si.id_solicitacao=s.id_solicitacao JOIN item i ON i.id_item=si.id_item JOIN usuario us ON us.id_usuario=s.id_usuario_solicitante JOIN usuario ud ON ud.id_usuario=i.id_usuario_publicador WHERE (s.id_usuario_solicitante=? OR i.id_usuario_publicador=?) AND s.status_soli<>'Excluída' ORDER BY s.id_solicitacao DESC LIMIT 100");$stmt->bind_param('ii',$id,$id);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();responder('ok','Conversas.',$rows);}
$stmt=$db->prepare('SELECT s.id_solicitacao FROM solicitacao s JOIN solicitacao_item si ON si.id_solicitacao=s.id_solicitacao JOIN item i ON i.id_item=si.id_item WHERE s.id_solicitacao=? AND (s.id_usuario_solicitante=? OR i.id_usuario_publicador=?)');$stmt->bind_param('iii',$sol,$id,$id);$stmt->execute();$existe=$stmt->get_result()->num_rows;$stmt->close();if(!$existe){http_response_code(403);responder('nok','Conversa não autorizada.');}
$stmt=$db->prepare('SELECT m.id_mensagem,m.conteudo,m.data_hora,m.id_usuario,u.nome AS autor FROM mensagem m JOIN usuario u ON u.id_usuario=m.id_usuario WHERE m.id_solicitacao=? ORDER BY m.id_mensagem ASC LIMIT 200');$stmt->bind_param('i',$sol);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();$stmt=$db->prepare('UPDATE mensagem SET lida=1 WHERE id_solicitacao=? AND id_usuario<>?');$stmt->bind_param('ii',$sol,$id);$stmt->execute();$stmt->close();responder('ok','Mensagens.',$rows);
